/**
 * Open-source notices bundled with the app (generated by scripts/generate-licenses.js from the installed
 * packages). The data is loaded the first time the Licenses screen opens, so it costs nothing at startup.
 */
export interface LicenseEntry {
  name: string;
  version: string | null;
  license: string | null;
  repository: string | null;
  /** Full license text(s) shipped inside the package; null when the package ships none. */
  text: string | null;
}

export function loadLicenses(): LicenseEntry[] {
  const data = require("./licenses.generated.json") as { packages?: LicenseEntry[] };
  return Array.isArray(data.packages) ? data.packages : [];
}
